for name,before,after,edits in items:
 p=pathlib.Path(name);source=p.read_text()
 assert hashlib.sha256(source.encode()).hexdigest()==before,name+' input changed'
 lines=source.splitlines(keepends=True)
 for a,b,text in reversed(edits):lines[a:b]=[text]
 result=''.join(lines)
 assert hashlib.sha256(result.encode()).hexdigest()==after,name+' output mismatch'
 p.write_text(result)
print('Verified source fixes:',len(items))
